import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"Emitter 選項","description":"在 `tspconfig.yaml` 設定，或在 CLI 以 `--option \\"tsp-asyncapi.<name>=<value>\\"` 傳入。","frontmatter":{"title":"Emitter 選項","description":"在 `tspconfig.yaml` 設定，或在 CLI 以 `--option \\"tsp-asyncapi.<name>=<value>\\"` 傳入。"},"headers":[],"relativePath":"zh-tw/reference/emitter-options.md","filePath":"zh-tw/reference/emitter-options.md","lastUpdated":1789025893000}'),o={name:"zh-tw/reference/emitter-options.md"};function d(c,e,n,r,p,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="emitter-選項" tabindex="-1">Emitter 選項 <a class="header-anchor" href="#emitter-選項" aria-label="Permalink to &quot;Emitter 選項&quot;">​</a></h1><p>在 <code>tspconfig.yaml</code> 設定，或在 CLI 以 <code>--option &quot;tsp-asyncapi.&lt;name&gt;=&lt;value&gt;&quot;</code> 傳入。</p><table tabindex="0"><thead><tr><th>選項</th><th>型別</th><th>預設值</th><th>效果</th></tr></thead><tbody><tr><td><code>file-type</code></td><td><code>&quot;yaml&quot; | &quot;json&quot;</code></td><td><code>yaml</code></td><td>文件的序列化格式。</td></tr><tr><td><code>output-file</code></td><td><code>string</code></td><td><code>asyncapi.{service-name-if-multiple}.{version}.{file-type}</code></td><td>輸出檔名或範本，寫在 <code>tsp-output/tsp-asyncapi/</code> 底下。</td></tr><tr><td><code>service</code></td><td><code>string</code></td><td>（所有已宣告的 service）</td><td>以完整 namespace 名稱精確選取一個 service，例如 <code>Company.Orders</code>。</td></tr><tr><td><code>version</code></td><td><code>string</code></td><td>（所有已宣告的根版本）</td><td>精確選取單一版本化 service 的版本 enum 值。</td></tr><tr><td><code>asyncapi-id</code></td><td><code>string</code></td><td>（省略）</td><td>輸出為文件頂層的 <code>id</code> 欄位，即應用程式的全域識別碼，慣例上用 URN。</td></tr><tr><td><code>default-content-type</code></td><td><code>string</code></td><td>（省略）</td><td>輸出為 <code>defaultContentType</code>。message 沒宣告 content type 時，payload 用這個。</td></tr><tr><td><code>preview-features</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>開啟預覽功能。保留的名稱是 <code>protobuf</code> 與 <code>avro</code>。</td></tr></tbody></table><p>沒設定的選項會整個從文件省略，不會輸出空值。</p><h2 id="用-tspconfig-yaml" tabindex="-1">用 <code>tspconfig.yaml</code> <a class="header-anchor" href="#用-tspconfig-yaml" aria-label="Permalink to &quot;用 \`tspconfig.yaml\`&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">emit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tsp-asyncapi&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;tsp-asyncapi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    output-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orders.yaml&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    file-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yaml&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    asyncapi-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;urn:com:example:orders&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    default-content-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/json&quot;</span></span></code></pre></div><h2 id="用-cli" tabindex="-1">用 CLI <a class="header-anchor" href="#用-cli" aria-label="Permalink to &quot;用 CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsp-asyncapi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tsp-asyncapi.file-type=json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --option</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tsp-asyncapi.asyncapi-id=urn:com:example:orders&quot;</span></span></code></pre></div><p>未知的選項名稱會在編譯時驗證失敗（<code>additionalProperties: false</code>）。打錯字會被抓到，不會被靜默忽略。<code>preview-features</code> 裡不是保留名稱的值也一樣會失敗，訊息會列出保留的名稱。</p><h2 id="service-文件與檔名" tabindex="-1">Service 文件與檔名 <a class="header-anchor" href="#service-文件與檔名" aria-label="Permalink to &quot;Service 文件與檔名&quot;">​</a></h2><p>預設每個標記 <code>@service</code> 的 namespace 都會產生一份 AsyncAPI 文件，包含只有 HTTP 操作的 service。沒有 messaging 宣告時會產生空的 AsyncAPI 文件，而不是依 HTTP decorator 猜測要不要輸出；不需要 HTTP 函式庫。</p><p><code>service</code> 精確比對區分大小寫的完整 namespace 名稱，不比對 title 或簡稱。找不到或無法唯一識別的名稱都是錯誤。從多個 service 中選取 <code>Company.Orders</code>，檔名仍然是 <code>asyncapi.Company.Orders.yaml</code>；篩選不會改變用來命名的原始 service 數量。</p><table tabindex="0"><thead><tr><th>Token</th><th>值</th></tr></thead><tbody><tr><td><code>{service-name}</code></td><td>原始完整 service namespace 名稱；沒有 service 的後備文件會省略。</td></tr><tr><td><code>{service-name-if-multiple}</code></td><td>原始程式有多個 service 時才填入上述名稱。</td></tr><tr><td><code>{version}</code></td><td>選定根版本的 enum 值；未版本化及只有相依版本的 service 會省略。</td></tr><tr><td><code>{file-type}</code></td><td><code>yaml</code> 或 <code>json</code>。</td></tr></tbody></table><p>省略的 token 也會移除緊接其後的 <code>.</code> 或 <code>/</code>。因此零個或一個未版本化 service 的預設檔名仍是 <code>asyncapi.yaml</code> 或 <code>asyncapi.json</code>。例如 <code>{service-name}/asyncapi.{file-type}</code> 會建立 service 子目錄。Service 與版本值會使用 UTF-8 百分比編碼，保留標點與 Unicode 的識別性，避免路徑分隔符、保留裝置名稱或結尾句點改變目的地。</p><p>只有一份選定文件時，仍可使用固定檔名 <code>output-file: orders.yaml</code>。多份文件需要能區分彼此的 token。emitter 會先解析並一起檢查所有路徑，包括不區分大小寫的碰撞。未知 token、無效檔名及碰撞都是錯誤；不會覆寫另一份文件，也不會自動加流水號。</p><h2 id="歸屬與共用合約" tabindex="-1">歸屬與共用合約 <a class="header-anchor" href="#歸屬與共用合約" aria-label="Permalink to &quot;歸屬與共用合約&quot;">​</a></h2><p>每個宣告屬於最近一層包含它的 <code>@service</code>。巢狀 service 是獨立邊界，重新開啟 namespace 也不例外。Channel、action、message、reply、server、security scheme、binding、tag、extension 與文件診斷，都會先依邊界選取，再分配 component key。</p><p>Service 自有的 <code>@message</code> 即使未使用也會保留。Messaging signature 可明確引用沒有 service 歸屬的共用 <code>@message</code>；有多個 service 時，未引用的無歸屬 message 不會輸出。Payload 與 header 可共用一般 domain model，即使 model 宣告在另一個 service 裡，也不會因此匯入該 service 的應用程式 metadata。引用其他 service 的 <code>@message</code> envelope 或 reply channel 則是錯誤；請改用本地 envelope 包裝共用資料。這也包含透過 discriminator 衍生子型別到達的外部 envelope；一般未標記的共用子型別仍可使用。</p><p>原始程式只有一個 service 時，無歸屬宣告保留舊有的隱含歸屬。沒有 service 時，仍產生舊有的全域後備文件。原始程式有多個 service 時，無歸屬的 channel 與 action 都有歧義，即使 <code>service</code> 只選一個也一樣；請把它們放到所屬 service 底下。在自有 channel 上具體套用的無歸屬繼承／template operation signature 是共用來源，不算額外的應用程式根節點。</p><p>emitter 會先解析所有選定文件，再開始寫檔。選取／歸屬錯誤、輸出碰撞、可見 security 定義歧義與 provider 拒絕，都會阻止整組輸出。未版本化文件保留既有 resolve/lower 層回報診斷後捨棄問題項目的行為；版本化或只有相依版本的檢視出現錯誤時，則會阻止整組輸出。Compiler 1.16 在 <code>noEmit</code> 時會略過 emitter，因此 emitter 專屬檢視驗證需要實際執行輸出流程。原始碼驗證仍涵蓋整份 TypeSpec 程式；選取 service 不會隱藏其他 service 的原始碼錯誤。</p><p>提供變更後 graph 的 adapter 必須傳入完整的 live 宣告邊界，包含保留的 alias-only message、channel 與 action。只探索 namespace map 無法證明清單完整。缺少或過期的輸入會回報 <code>incomplete-effective-document</code> 或 <code>stale-effective-declaration</code> 並拒絕 context。原始 source model 可用於診斷或清單，不能取代 live 宣告或 artifact。明確傳入完全相同的原始 graph 時，仍保留一般 alias 行為。</p><h2 id="版本選取" tabindex="-1">版本選取 <a class="header-anchor" href="#版本選取" aria-label="Permalink to &quot;版本選取&quot;">​</a></h2><p><code>version</code> 可選取根版本 enum 的精確<strong>值</strong>，不是成員名稱，也不是 <code>@info.version</code>。 省略時會輸出所有已宣告的根版本。選取時必須只有一個明確的版本化 service； 原始程式有多個 service 時，可搭配 <code>service</code> 選項。</p><p>根版本文件使用選定值作為 <code>info.version</code>，並對作者提供的衝突中繼資料回報警告。 未版本化及只有相依版本的 service 保留自己的中繼資料。版本化根檢視的檔名一定 保留版本 token，即使只選取一個版本也一樣。</p><p>Compiler 1.16 / versioning 0.86 整合、alias、相依版本及限制，請參閱 <a href="./../guide/versioning">版本化契約</a>。</p><h2 id="預覽功能" tabindex="-1">預覽功能 <a class="header-anchor" href="#預覽功能" aria-label="Permalink to &quot;預覽功能&quot;">​</a></h2><p>預覽功能會改變輸出的文件。保留的名稱有兩個：<code>protobuf</code> 與 <code>avro</code>。本版兩個都可以使用。背後沒有實作的名稱會回報 <code>preview-feature-unavailable</code>，而且不寫出檔案。請求同時指名可用與不可用的功能時，整份一樣會被拒絕。</p><p><code>protobuf</code> 讓帶有官方 <code>TypeSpec.Protobuf</code> decorator 的 model 拿到 proto3 payload。<a href="./../guide/protobuf-payloads">Protobuf payload 指南</a>說明它寫出什麼。</p><p><code>avro</code> 讓帶有 <code>tsp-avro</code> <code>@Avro.avroRecord</code> decorator 的 model 拿到 Avro payload。payload 是以物件寫出的，因為 Avro 就是 JSON。<code>tsp-avro</code> 是這個 emitter 的選用 peer dependency。開啟這個功能的專案要自行安裝它。</p><p>兩個功能可以同時開啟。同一個 model 只能帶其中一組 decorator。兩組都帶的 model 會回報 <code>conflicting-generated-schema-source</code>，而且不寫出檔案。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>預覽功能被拒絕時不會輸出任何東西。在錯誤旁邊寫出一份文件，等於忽略了請求卻不說明。</p></div>`,31)])])}const m=t(o,[["render",d]]);export{k as __pageData,m as default};
